// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { CustomAITypesV1 as T } from "./CustomAITypesV1.sol";
import { ICustomAIFeeModuleV1 } from "./ICustomAIFeeModuleV1.sol";

/// @notice Bounded, read-only fee evaluation. No module state changes survive because none are permitted.
library CustomAIModuleCallV1 {
    uint256 internal constant MODULE_GAS = 100_000;
    uint256 internal constant CALLER_RESERVE = 50_000;

    enum Status {
        Applied,
        NoModule,
        CodeChanged,
        CallFailed,
        InvalidResponse,
        Expired,
        ConfigurationChanged,
        FeeCapExceeded
    }

    error InsufficientEvaluationGas();

    function evaluate(T.ModuleBinding memory binding, T.SwapContext memory context)
        internal
        view
        returns (uint16 additionalBps, Status status)
    {
        if (binding.instance == address(0)) return (0, Status.NoModule);
        address instance = binding.instance;
        if (instance.code.length == 0 || instance.codehash != binding.runtimeHash) return (0, Status.CodeChanged);
        bytes memory input = abi.encodeCall(ICustomAIFeeModuleV1.quoteFee, (context));
        uint256[4] memory output;
        bool success;
        uint256 size;
        // Reserve enough for EIP-150 and response handling. Insufficient caller gas must not silently lower fees.
        if (gasleft() < MODULE_GAS + MODULE_GAS / 63 + CALLER_RESERVE) revert InsufficientEvaluationGas();
        assembly ("memory-safe") {
            success := staticcall(MODULE_GAS, instance, add(input, 32), mload(input), output, 128)
            size := returndatasize()
        }
        if (!success) return (0, Status.CallFailed);
        // Inspect words before narrowing instead of abi.decode, which could revert on malicious ABI padding.
        if (
            size != 128 || output[0] != uint256(bytes32(ICustomAIFeeModuleV1.quoteFee.selector))
                || output[1] > type(uint16).max || output[2] > type(uint64).max
        ) return (0, Status.InvalidResponse);
        if (bytes32(output[3]) != binding.configurationHash) return (0, Status.ConfigurationChanged);
        if (output[2] < block.timestamp) return (0, Status.Expired);
        if (output[1] > T.MAX_ADDITIONAL_BPS) return (0, Status.FeeCapExceeded);
        return (uint16(output[1]), Status.Applied);
    }
}

src/custom-ai/CustomAIPriceV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { FullMath } from "@uniswap/v4-core/src/libraries/FullMath.sol";
import { TickMath } from "@uniswap/v4-core/src/libraries/TickMath.sol";
import { CustomAITypesV1 as T } from "./CustomAITypesV1.sol";

/// @notice Conservative USD valuation of the fixed supply at the actual initial pool tick.
library CustomAIPriceV1 {
    uint64 internal constant MAX_AGE = 120;
    uint256 internal constant MAX_START_USD_E18 = T.START_FDV_USD_E18 * 10_061 / 10_000;
    error InvalidPrice();
    error InvalidStartValue();

    /// @notice Gross quote input worth at least 0.01 ETH, rounded up to a whole quote unit.
    function minimumInitialBuy(uint8 decimals, T.Price memory price) internal pure returns (uint256) {
        if (
            decimals > 36 || price.quoteUsdE18 == 0 || price.quoteUsdE18 > 1e36 || price.ethUsdE18 == 0
                || price.ethUsdE18 > 1e36
        ) revert InvalidPrice();
        return FullMath.mulDivRoundingUp(
            T.MIN_INITIAL_BUY_ETH * price.ethUsdE18, 10 ** uint256(decimals), price.quoteUsdE18 * 1 ether
        );
    }

    function validate(bool token0, int24 tick, uint8 decimals, T.Price memory price)
        internal
        view
        returns (uint256 lower, uint256 upper)
    {
        if (
            price.quoteUsdE18 == 0 || price.quoteUsdE18 > 1e36 || price.ethUsdE18 == 0 || price.ethUsdE18 > 1e36
                || decimals > 36 || price.observedAt > block.timestamp || block.timestamp - price.observedAt > MAX_AGE
                || price.validUntil < block.timestamp || price.validUntil < price.observedAt
                || uint256(price.validUntil) > uint256(price.observedAt) + MAX_AGE
        ) revert InvalidPrice();
        if (
            tick % T.TICK_SPACING != 0 || tick <= TickMath.minUsableTick(T.TICK_SPACING)
                || tick >= TickMath.maxUsableTick(T.TICK_SPACING)
        ) revert InvalidStartValue();
        (lower, upper) = bounds(token0, tick, decimals, price.quoteUsdE18);
        // 60-tick granularity: choose the first grid point conservatively at/above $15k, at most +0.61%.
        if (lower < T.START_FDV_USD_E18 || upper > MAX_START_USD_E18) revert InvalidStartValue();
        (uint256 prior,) =
            bounds(token0, token0 ? tick - T.TICK_SPACING : tick + T.TICK_SPACING, decimals, price.quoteUsdE18);
        if (prior >= T.START_FDV_USD_E18) revert InvalidStartValue();
    }

    function bounds(bool token0, int24 tick, uint8 decimals, uint256 quoteUsdE18)
        internal
        pure
        returns (uint256 lower, uint256 upper)
    {
        uint160 sqrt = TickMath.getSqrtPriceAtTick(tick);
        uint256 quoteAmount;
        uint256 quoteUpper;
        if (sqrt <= type(uint128).max) {
            uint256 ratio = uint256(sqrt) * sqrt;
            quoteAmount = token0
                ? FullMath.mulDiv(ratio, T.TOKEN_SUPPLY, 1 << 192)
                : FullMath.mulDiv(1 << 192, T.TOKEN_SUPPLY, ratio);
            quoteUpper = token0
                ? FullMath.mulDivRoundingUp(ratio, T.TOKEN_SUPPLY, 1 << 192)
                : FullMath.mulDivRoundingUp(1 << 192, T.TOKEN_SUPPLY, ratio);
        } else {
            // The Q128 ratio is rounded down. Bound the inverse in the conservative direction.
            uint256 ratio = FullMath.mulDiv(sqrt, sqrt, 1 << 64);
            quoteAmount = token0
                ? FullMath.mulDiv(ratio, T.TOKEN_SUPPLY, 1 << 128)
                : FullMath.mulDiv(1 << 128, T.TOKEN_SUPPLY, ratio + 1);
            quoteUpper = token0
                ? FullMath.mulDivRoundingUp(ratio + 1, T.TOKEN_SUPPLY, 1 << 128)
                : FullMath.mulDivRoundingUp(1 << 128, T.TOKEN_SUPPLY, ratio);
        }
        uint256 scale = 10 ** uint256(decimals);
        lower = FullMath.mulDiv(quoteAmount, quoteUsdE18, scale);
        upper = FullMath.mulDivRoundingUp(quoteUpper, quoteUsdE18, scale);
    }
}

src/custom-ai/CustomAIRewardVaultV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { ReentrancyGuardTransient } from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import { CustomAITransfersV1 as X } from "./CustomAITransfersV1.sol";
import { CustomAITypesV1 as T } from "./CustomAITypesV1.sol";
import { ICustomAIRewardModuleV1 } from "./ICustomAIRewardModuleV1.sol";

/// @notice Isolated, funded creator/reward balances. No module has custody, allowance or execution authority.
contract CustomAIRewardVaultV1 is ReentrancyGuardTransient {
    uint256 public constant MODULE_GAS = 100_000;
    address public immutable quote;
    bytes32 public immutable quoteCodeHash;
    address public immutable creatorRecipient;
    uint16 public immutable creatorShareBps;
    address public immutable rewardModule;
    bytes32 public immutable moduleCodeHash;
    bytes32 public immutable configurationHash;
    uint256 public totalReceived;
    uint256 public creatorReceived;
    uint256 public creatorClaimed;
    uint256 public availableRewards;
    uint256 public reservedRewards;
    mapping(bytes32 => bool) public allocated;
    mapping(address => uint256) public claimable;

    error InvalidConfiguration();
    error Insolvent();
    error NothingToClaim();
    error InsufficientEvaluationGas();

    event Funded(uint256 amount, uint256 creatorAmount, uint256 rewardAmount);
    event RewardAllocated(bytes32 indexed actionId, address indexed beneficiary, uint256 amount);
    event Claimed(address indexed beneficiary, bool creator, uint256 amount);

    constructor(address quote_, T.Rewards memory r) {
        if (
            quote_.code.length == 0 || r.creatorRecipient == address(0) || r.creatorRecipient == address(this)
                || r.creatorShareBps > T.BPS
        ) revert InvalidConfiguration();
        if (r.module.instance == address(0)) {
            if (r.creatorShareBps != T.BPS || r.module.runtimeHash != 0 || r.module.configurationHash != 0) {
                revert InvalidConfiguration();
            }
        } else if (r.module.instance.code.length == 0 || r.module.instance.codehash != r.module.runtimeHash) {
            revert InvalidConfiguration();
        }
        quote = quote_;
        quoteCodeHash = quote_.codehash;
        creatorRecipient = r.creatorRecipient;
        creatorShareBps = r.creatorShareBps;
        rewardModule = r.module.instance;
        moduleCodeHash = r.module.runtimeHash;
        configurationHash = r.module.configurationHash;
    }

    function accountedBalance() public view returns (uint256) {
        return creatorReceived - creatorClaimed + availableRewards + reservedRewards;
    }

    function sync() external nonReentrant {
        _sync();
    }

    /// @notice Permissionless proposal evaluation; failure leaves funds available and never affects trading.
    function allocate(bytes32 actionId) external nonReentrant returns (bool) {
        _sync();
        address module = rewardModule;
        if (
            actionId == 0 || allocated[actionId] || module == address(0) || module.codehash != moduleCodeHash
                || availableRewards == 0
        ) return false;
        bytes memory input =
            abi.encodeCall(ICustomAIRewardModuleV1.quoteReward, (actionId, address(this), quote, availableRewards));
        uint256[5] memory output;
        bool ok;
        uint256 size;
        if (gasleft() < MODULE_GAS + MODULE_GAS / 63 + 75_000) revert InsufficientEvaluationGas();
        assembly ("memory-safe") {
            ok := staticcall(MODULE_GAS, module, add(input, 32), mload(input), output, 160)
            size := returndatasize()
        }
        if (
            !ok || size != 160 || output[0] != uint256(bytes32(ICustomAIRewardModuleV1.quoteReward.selector))
                || output[1] == 0 || output[1] > type(uint160).max || address(uint160(output[1])) == address(this)
                || output[2] == 0 || output[2] > availableRewards || output[3] > type(uint64).max
                || output[3] < block.timestamp || bytes32(output[4]) != configurationHash
        ) return false;
        address beneficiary = address(uint160(output[1]));
        allocated[actionId] = true;
        availableRewards -= output[2];
        reservedRewards += output[2];
        claimable[beneficiary] += output[2];
        emit RewardAllocated(actionId, beneficiary, output[2]);
        return true;
    }

    function claimCreator() external nonReentrant returns (uint256 amount) {
        _sync();
        amount = creatorReceived - creatorClaimed;
        if (amount == 0) revert NothingToClaim();
        creatorClaimed += amount;
        X.push(IERC20(quote), creatorRecipient, amount);
        emit Claimed(creatorRecipient, true, amount);
    }

    /// @notice Anyone can deliver an earned reward, but can never change its destination.
    function claimReward(address beneficiary) external nonReentrant returns (uint256 amount) {
        _sync();
        amount = claimable[beneficiary];
        if (amount == 0) revert NothingToClaim();
        claimable[beneficiary] = 0;
        reservedRewards -= amount;
        X.push(IERC20(quote), beneficiary, amount);
        emit Claimed(beneficiary, false, amount);
    }

    function _sync() private {
        if (quote.codehash != quoteCodeHash) revert InvalidConfiguration();
        uint256 balance = IERC20(quote).balanceOf(address(this));
        uint256 accounted = accountedBalance();
        if (balance < accounted) revert Insolvent();
        uint256 incoming = balance - accounted;
        if (incoming == 0) return;
        // Split cumulatively so repeated tiny syncs cannot divert the creator's rounding share.
        totalReceived += incoming;
        uint256 creatorTotal =
            totalReceived / T.BPS * creatorShareBps + (totalReceived % T.BPS) * creatorShareBps / T.BPS;
        uint256 creatorAdded = creatorTotal - creatorReceived;
        creatorReceived = creatorTotal;
        availableRewards += incoming - creatorAdded;
        emit Funded(incoming, creatorAdded, incoming - creatorAdded);
    }
}

src/custom-ai/CustomAISwapRouterV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { ReentrancyGuardTransient } from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import { IPoolManager } from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import { IUnlockCallback } from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import { PoolKey } from "@uniswap/v4-core/src/types/PoolKey.sol";
import { SwapParams } from "@uniswap/v4-core/src/types/PoolOperation.sol";
import { BalanceDelta } from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import { Currency } from "@uniswap/v4-core/src/types/Currency.sol";
import { CustomAITransfersV1 as X } from "./CustomAITransfersV1.sol";
import { CustomAITypesV1 as T } from "./CustomAITypesV1.sol";

/// @notice Full-fill ERC20 swaps with caller-only funding, explicit price/fee limits and no residual custody.
contract CustomAISwapRouterV1 is ReentrancyGuardTransient, IUnlockCallback {
    IPoolManager public immutable poolManager;
    bytes32 public immutable managerCodeHash;
    bytes32 private _context;

    event SwapSettled(address indexed payer, address indexed recipient, address indexed input, address output, uint256 paid, uint256 received);

    error InvalidSwap();
    error DeadlineExpired();
    error Unauthorized();
    error SlippageExceeded();
    error InvalidSettlement();

    struct Order {
        address payer;
        address recipient;
        PoolKey key;
        SwapParams params;
        uint256 limit;
        uint16 maxFeeBps;
    }

    constructor(IPoolManager manager) {
        if (address(manager).code.length == 0) revert InvalidSwap();
        poolManager = manager;
        managerCodeHash = address(manager).codehash;
    }

    /// @param limit Minimum received for exact input; maximum paid for exact output. Fees are included.
    function swap(
        PoolKey calldata key,
        SwapParams calldata params,
        uint256 limit,
        uint16 maxFeeBps,
        address recipient,
        uint64 deadline
    ) external nonReentrant returns (uint256 paid, uint256 received) {
        if (block.timestamp > deadline) revert DeadlineExpired();
        if (
            address(poolManager).codehash != managerCodeHash || recipient == address(0) || recipient == address(this)
                || recipient == address(poolManager) || Currency.unwrap(key.currency0).code.length == 0
                || Currency.unwrap(key.currency1).code.length == 0 || params.amountSpecified == 0
                || params.amountSpecified > int256(T.MAX_AMOUNT) || params.amountSpecified < -int256(T.MAX_AMOUNT)
                || maxFeeBps < T.PLATFORM_BPS || maxFeeBps > T.MAX_TOTAL_BPS
        ) revert InvalidSwap();
        bytes memory data = abi.encode(Order(msg.sender, recipient, key, params, limit, maxFeeBps));
        _context = keccak256(data);
        (paid, received) = abi.decode(poolManager.unlock(data), (uint256, uint256));
        if (_context != 0) revert Unauthorized();
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (
            msg.sender != address(poolManager) || !_reentrancyGuardEntered() || _context == 0
                || keccak256(data) != _context
        ) revert Unauthorized();
        _context = 0;
        Order memory o = abi.decode(data, (Order));
        BalanceDelta delta = poolManager.swap(o.key, o.params, abi.encode(o.maxFeeBps));
        int128 inputDelta = o.params.zeroForOne ? delta.amount0() : delta.amount1();
        int128 outputDelta = o.params.zeroForOne ? delta.amount1() : delta.amount0();
        if (inputDelta >= 0 || outputDelta <= 0) revert InvalidSettlement();
        uint256 paid = uint256(-int256(inputDelta));
        uint256 received = uint256(int256(outputDelta));
        if (o.params.amountSpecified < 0) {
            if (paid != uint256(-o.params.amountSpecified) || received < o.limit) revert SlippageExceeded();
        } else if (received != uint256(o.params.amountSpecified) || paid > o.limit) {
            revert SlippageExceeded();
        }
        Currency input = o.params.zeroForOne ? o.key.currency0 : o.key.currency1;
        Currency output = o.params.zeroForOne ? o.key.currency1 : o.key.currency0;
        poolManager.sync(input);
        X.pull(IERC20(Currency.unwrap(input)), o.payer, address(poolManager), paid);
        if (poolManager.settle() != paid) revert InvalidSettlement();
        IERC20 outAsset = IERC20(Currency.unwrap(output));
        uint256 beforeRecipient = outAsset.balanceOf(o.recipient);
        uint256 beforeManager = outAsset.balanceOf(address(poolManager));
        poolManager.take(output, o.recipient, received);
        if (
            outAsset.balanceOf(o.recipient) != beforeRecipient + received
                || outAsset.balanceOf(address(poolManager)) != beforeManager - received
        ) revert InvalidSettlement();
        emit SwapSettled(o.payer, o.recipient, Currency.unwrap(input), Currency.unwrap(output), paid, received);
        return abi.encode(paid, received);
    }
}

